<div class="address-bar-with-context" data-bind="attr: { id: id }">
    <!-- ko if: viewModel.isContextVisible -->
    <select data-bind="
        options: viewModel.contextOptions,
        optionsText: 'displayName',
        value: viewModel.displaySelectedContext,
        enable: viewModel.isContextEnabled,
        valueAllowUnset: true,
        attr: { 'aria-label': viewModel.strings.viewContextAriaLabel }
    "></select>
    <!-- /ko -->
    <div class="address-bar" role="button" tabindex="0" data-bind="
        hasFocus: viewModel.addressBarHasFocus,
        click: onAddressBarClick,
        event: { keydown: onAddressBarKeydown },
        attr: { 'aria-label': viewModel.strings.addressBarAriaLabel, 'aria-disabled': !viewModel.isEditable() }">

        <div class="input-with-prefix" data-bind="visible: viewModel.isEditing">
            <input data-bind="
                textInput: viewModel.workingPath,
                hasFocus: viewModel.addressBarInputHasFocus,
                event: { keydown: onAddressBarInputKeydown },
                keydownBubble: false
            "/>
        </div>

        <div class="address-bar-breadcrumb-list" data-bind="hidden: viewModel.isEditing">
            <div class="address-bar-collapsed-breadcrumbs" data-bind="visible: hasCollapsedBreadcrumbs">
                <button title="more breadcrumbs" data-bind="
                    click: onCollapsedBreadcrumbGroupClick,
                    clickBubble: false,
                    event: { keydown: onCollapseBreadcrumbGroupKeydown },
                    keydownBubble: false,
                    attr: { title: viewModel.strings.moreBreadcrumbsLabel, 'aria-label': viewModel.strings.moreBreadcrumbsLabel }">
                    <div class="breadcrumb-collapsed-group-icon">
                        <se-icon params="with: { name: viewModel.icons.moreBreadcrumbs }"></se-icon>
                    </div>
                </button>
            </div>
            <!-- ko foreach: visibleBreadcrumbs -->
            <div class="breadcrumb">
                <button data-bind="
                    text: displayName,
                    click: (data, event) => $component.onBreadcrumbClick(data, event),
                    clickBubble: false,
                    event: { keydown: (data, event) => $component.onBreadcrumbKeydown(data, event) },
                    keydownBubble: false,
                    css: { 'overflow': $component.hasOverflow() },
                    attr: {
                        title: displayName,
                        'aria-label': displayName,
                        'aria-roledescription': $component.viewModel.strings.breadcrumbAriaRoleDescription
                    }">
                </button>
                <div class="breadcrumb-delimiter-icon" data-bind="visible: !$component.viewModel.isLastBreadcrumb($data)">
                    <se-icon params="with: { name: $component.viewModel.icons.breadcrumbConnector }"></se-icon>
                </div>
            </div>
            <!-- /ko -->
        </div>
    </div>
</div>
